341	// createCheckpointOnMetadataBranchFull creates a checkpoint on the entire/checkpoints/v1 branch
342	// with a caller-specified checkpoint ID and timestamp.
343	func createCheckpointOnMetadataBranchFull(t *testing.T, repo *git.Repository, sessionID string, checkpointID id.CheckpointID, createdAt time.Time) id.CheckpointID {
344		t.Helper()
345	
346		// Get existing metadata branch or create it
347		if err := strategy.EnsurePrimaryRef(t.Context(), repo); err != nil {
348			t.Fatalf("Failed to ensure metadata branch: %v", err)
349		}
350	
351		refName := plumbing.NewBranchReferenceName(paths.MetadataBranchName)
352		ref, err := repo.Reference(refName, true)
353		if err != nil {
354			t.Fatalf("Failed to get metadata branch ref: %v", err)
355		}
356	
357		parentCommit, err := repo.CommitObject(ref.Hash())
358		if err != nil {
359			t.Fatalf("Failed to get parent commit: %v", err)
360		}
361	
362		// Create metadata content
363		metadataJSON := fmt.Sprintf(`{
364	  "checkpoint_id": %q,
365	  "session_id": %q,
366	  "created_at": %q
367	}`, checkpointID.String(), sessionID, createdAt.Format(time.RFC3339))
368	
369		// Create blob for metadata
370		blob := repo.Storer.NewEncodedObject()
371		blob.SetType(plumbing.BlobObject)
372		writer, err := blob.Writer()
373		if err != nil {
374			t.Fatalf("Failed to create blob writer: %v", err)
375		}
376		if _, err := writer.Write([]byte(metadataJSON)); err != nil {
377			t.Fatalf("Failed to write blob: %v", err)
378		}
379		if err := writer.Close(); err != nil {
380			t.Fatalf("Failed to close writer: %v", err)
381		}
382		metadataBlobHash, err := repo.Storer.SetEncodedObject(blob)
383		if err != nil {
384			t.Fatalf("Failed to store blob: %v", err)
385		}
386	
387		// Create session log blob
388		logBlob := repo.Storer.NewEncodedObject()
389		logBlob.SetType(plumbing.BlobObject)
390		logWriter, err := logBlob.Writer()
391		if err != nil {
392			t.Fatalf("Failed to create log blob writer: %v", err)
393		}
394		if _, err := logWriter.Write([]byte(`{"type":"test"}`)); err != nil {
395			t.Fatalf("Failed to write log blob: %v", err)
396		}
397		if err := logWriter.Close(); err != nil {
398			t.Fatalf("Failed to close log writer: %v", err)
399		}
400		logBlobHash, err := repo.Storer.SetEncodedObject(logBlob)
401		if err != nil {
402			t.Fatalf("Failed to store log blob: %v", err)
403		}
404	
405		// Build tree structure: <id[:2]>/<id[2:]>/metadata.json
406		shardedPath := checkpointID.Path()
407		checkpointIDStr := checkpointID.String()
408	
409		// Create checkpoint tree with metadata and transcript files
410		// Entries must be sorted alphabetically
411		checkpointTree := object.Tree{
412			Entries: []object.TreeEntry{
413				{Name: paths.TranscriptFileName, Mode: filemode.Regular, Hash: logBlobHash},
414				{Name: paths.MetadataFileName, Mode: filemode.Regular, Hash: metadataBlobHash},
415			},
416		}
417		checkpointTreeObj := repo.Storer.NewEncodedObject()
418		if err := checkpointTree.Encode(checkpointTreeObj); err != nil {
419			t.Fatalf("Failed to encode checkpoint tree: %v", err)
420		}
421		checkpointTreeHash, err := repo.Storer.SetEncodedObject(checkpointTreeObj)
422		if err != nil {
423			t.Fatalf("Failed to store checkpoint tree: %v", err)
424		}
425	
426		// Create inner shard tree (id[2:])
427		innerTree := object.Tree{
428			Entries: []object.TreeEntry{
429				{Name: checkpointIDStr[2:], Mode: filemode.Dir, Hash: checkpointTreeHash},
430			},
431		}
432		innerTreeObj := repo.Storer.NewEncodedObject()
433		if err := innerTree.Encode(innerTreeObj); err != nil {
434			t.Fatalf("Failed to encode inner tree: %v", err)
435		}
436		innerTreeHash, err := repo.Storer.SetEncodedObject(innerTreeObj)
437		if err != nil {
438			t.Fatalf("Failed to store inner tree: %v", err)
439		}
440	
441		// Get existing tree entries from parent
442		parentTree, err := parentCommit.Tree()
443		if err != nil {
444			t.Fatalf("Failed to get parent tree: %v", err)
445		}
446	
447		// Build new root tree with shard bucket
448		var rootEntries []object.TreeEntry
449		for _, entry := range parentTree.Entries {
450			if entry.Name != shardedPath[:2] {
451				rootEntries = append(rootEntries, entry)
452			}
453		}
454		rootEntries = append(rootEntries, object.TreeEntry{
455			Name: checkpointIDStr[:2],
456			Mode: filemode.Dir,
457			Hash: innerTreeHash,
458		})
459	
460		rootTree := object.Tree{Entries: rootEntries}
461		rootTreeObj := repo.Storer.NewEncodedObject()
462		if err := rootTree.Encode(rootTreeObj); err != nil {
463			t.Fatalf("Failed to encode root tree: %v", err)
464		}
465		rootTreeHash, err := repo.Storer.SetEncodedObject(rootTreeObj)
466		if err != nil {
467			t.Fatalf("Failed to store root tree: %v", err)
468		}
469	
470		// Create commit on metadata branch
471		commit := &object.Commit{
472			Author: object.Signature{
473				Name:  "Test",
474				Email: "test@example.com",
475				When:  parentCommit.Author.When,
476			},
477			Committer: object.Signature{
478				Name:  "Test",
479				Email: "test@example.com",
480				When:  parentCommit.Author.When,
481			},
482			Message:      "Add checkpoint metadata",
483			TreeHash:     rootTreeHash,
484			ParentHashes: []plumbing.Hash{parentCommit.Hash},
485		}
486		commitObj := repo.Storer.NewEncodedObject()
487		if err := commit.Encode(commitObj); err != nil {
488			t.Fatalf("Failed to encode commit: %v", err)
489		}
490		commitHash, err := repo.Storer.SetEncodedObject(commitObj)
491		if err != nil {
492			t.Fatalf("Failed to store commit: %v", err)
493		}
494	
495		// Update metadata branch ref
496		newRef := plumbing.NewHashReference(refName, commitHash)
497		if err := repo.Storer.SetReference(newRef); err != nil {
498			t.Fatalf("Failed to update metadata branch: %v", err)
499		}
500	
501		return checkpointID
