21	)
22	
23	// checkpointPrefixShape matches strings that could be a checkpoint ID or a
24	// prefix of one (legacy 12-hex or 26-char Crockford ULID). Targets that can't
25	// be checkpoint IDs (e.g. "feature/foo") skip the store lookup and its
26	// remote-fetch fallback entirely.
27	var checkpointPrefixShape = regexp.MustCompile(`^(?:[0-9a-f]{1,12}|[REDACTED]{1,26})$`)
28	
29	var errNoResumeCommit = errors.New("no commit found")
30	
31	func newCheckpointResumeCmd() *cobra.Command {
32		var checkpointFlag string
33		var commitFlag string
34		var branchFlag string
35		var force bool
36	
37		cmd := &cobra.Command{
38			Use:    "resume [checkpoint-id | commit-sha | branch]",
39			Short:  "Resume the agent session(s) recorded in a checkpoint",
40			Hidden: true,
41			Long: `Resume agent sessions from a committed checkpoint.
42	
43	The target can be a checkpoint ID (or prefix), a commit SHA (or ref) whose
44	message carries an Entire-Checkpoint trailer, or a branch name. Auto-detection
45	tries checkpoint ID first, then local branch, then commit; use the flags to
46	force one interpretation.
47	
48	For a checkpoint or commit target, the branch containing the checkpoint's
49	commit is checked out at its current tip before the session logs are
50	restored. If no local branch contains it, the session logs are restored
51	without switching branches. A branch target checks the branch out and
52	resumes its latest checkpoint.
53	
54	With no target, shows recent checkpoints: an interactive picker on a
55	terminal, a plain-text list otherwise.
56	
57	Existing local session logs are never overwritten unless --force is given.`,
58			Args: cobra.MaximumNArgs(1),
59			RunE: func(cmd *cobra.Command, args []string) error {
60				if checkDisabledGuard(cmd.Context(), cmd.OutOrStdout()) {
61					return nil
62				}
63				var positional string
64				if len(args) > 0 {
65					positional = args[0]
66					if checkpointFlag != "" || commitFlag != "" || branchFlag != "" {
67						return errors.New("cannot combine positional argument with --checkpoint, --commit, or --branch")
68					}
69				}
70				if _, err := paths.WorktreeRoot(cmd.Context()); err == nil {
71					logging.SetLogLevelGetter(GetLogLevel)
72					if err := logging.Init(cmd.Context(), ""); err == nil {
73						defer logging.Close()
74					}
75				}
76				external.DiscoverAndRegister(cmd.Context())
77				return runCheckpointResume(cmd.Context(), cmd, positional, checkpointFlag, commitFlag, branchFlag, force)
78			},
79		}
80	
81		cmd.Flags().StringVarP(&checkpointFlag, "checkpoint", "c", "", "Resume a specific checkpoint (ID or prefix)")
82		cmd.Flags().StringVar(&commitFlag, "commit", "", "Resume the checkpoint referenced by a commit (SHA or ref)")
83		cmd.Flags().StringVar(&branchFlag, "branch", "", "Resume the latest checkpoint on a branch")
84		cmd.Flags().BoolVarP(&force, "force", "f", false, "Skip confirmations and overwrite existing local session logs")
85		cmd.MarkFlagsMutuallyExclusive("checkpoint", "commit", "branch")
86	
87		return cmd
88	}
89	
90	func runCheckpointResume(ctx context.Context, cmd *cobra.Command, target, checkpointFlag, commitFlag, branchFlag string, force bool) error {
91		if branchFlag != "" {
92			return runResume(ctx, cmd, branchFlag, force)
93		}
94	
95		lookup, err := newExplainCheckpointLookup(ctx)
96		if err != nil {
97			return err
98		}
99		initialLookup := lookup
100		defer func() {
101			if lookup != nil && lookup != initialLookup {
102				_ = lookup.Close()
103			}
104			_ = initialLookup.Close()
105		}()
106	
107		switch {
108		case checkpointFlag != "":
109			var matches []id.CheckpointID
110			matches, lookup = matchCheckpointPrefixWithRemoteFallback(ctx, cmd.ErrOrStderr(), lookup, checkpointFlag)
111			return resumeMatchedCheckpoints(ctx, cmd, lookup, checkpointFlag, matches, force)
112		case commitFlag != "":
113			return resumeCommitTarget(ctx, cmd, lookup, commitFlag, force)
114		case target != "":
115			var resumeErr error
116			lookup, resumeErr = resumeAutoTarget(ctx, cmd, lookup, target, force)
117			return resumeErr
118		default:
119			return runCheckpointResumePicker(ctx, cmd, lookup, force)
120		}
121	}
122	
123	// resumeAutoTarget resolves a positional target: checkpoint-ID prefix first
124	// (local, then remote fallback only if nothing local matches), then local
125	// branch, then commit revision. Only local branches are auto-detected as
126	// branch targets: branchCommit also resolves origin/<name> and, for a target
127	// like "HEAD", would wrongly match refs/remotes/origin/HEAD, misrouting
128	// revision syntax that must fall through to commit resolution instead
129	// (--branch still handles remote-only branches explicitly via runResume).
130	// Returns the possibly-swapped lookup so the caller's deferred close stays
131	// correct.
132	func resumeAutoTarget(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, target string, force bool) (*explainCheckpointLookup, error) {
133		shapedLikeCheckpoint := checkpointPrefixShape.MatchString(target)
134		if shapedLikeCheckpoint {
135			if matches := matchCheckpointPrefix(lookup, target); len(matches) > 0 {
136				return lookup, resumeMatchedCheckpoints(ctx, cmd, lookup, target, matches, force)
137			}
138		}
139	
140		if branchExistsLocally(lookup.repo, target) {
141			return lookup, runResume(ctx, cmd, target, force)
142		}
143	
144		if shapedLikeCheckpoint {
145			var matches []id.CheckpointID
146			matches, lookup = matchCheckpointPrefixWithRemoteFallback(ctx, cmd.ErrOrStderr(), lookup, target)
147			if len(matches) > 0 {
148				return lookup, resumeMatchedCheckpoints(ctx, cmd, lookup, target, matches, force)
149			}
150		}
151	
152		err := resumeCommitTarget(ctx, cmd, lookup, target, force)
153		if errors.Is(err, errNoResumeCommit) {
154			return lookup, fmt.Errorf("nothing matched %q as a checkpoint ID, branch, or commit\nHint: run 'entire checkpoint list' to see available checkpoints", target)
155		}
156		return lookup, err
157	}
158	
159	func resumeMatchedCheckpoints(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, prefix string, matches []id.CheckpointID, force bool) error {
160		switch len(matches) {
161		case 0:
162			return fmt.Errorf("no committed checkpoint matched %q\nHint: run 'entire checkpoint list' to see available checkpoints", prefix)
163		case 1:
164			return resumeResolvedCheckpoint(ctx, cmd, lookup, matches[0], force)
165		default:
166			renderAmbiguousPrefixFailure(cmd.ErrOrStderr(), prefix, "committed checkpoints", buildAmbiguousCheckpointMatches(matches, lookup.committed))
167			return NewSilentError(fmt.Errorf("%w: checkpoint prefix %s matches %d checkpoints", errAmbiguousCommitPrefix, prefix, len(matches)))
168		}
169	}
170	
171	// resumeCommitTarget resolves ref to a commit and resumes the checkpoint its
172	// Entire-Checkpoint trailer references. Multiple trailers (squash merge)
173	// resolve to the newest checkpoint by CreatedAt.
174	func resumeCommitTarget(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, ref string, force bool) error {
175		w := cmd.OutOrStdout()
176		errW := cmd.ErrOrStderr()
177	
178		hash, ambiguousMatches, err := resolveCommitUnambiguous(lookup.repo, ref)
179		if err != nil {
180			if errors.Is(err, errAmbiguousCommitPrefix) {
181				renderAmbiguousPrefixFailure(errW, ref, "commits", buildAmbiguousCommitMatches(lookup.repo, ambiguousMatches))
182				return NewSilentError(err)
183			}
184			return fmt.Errorf("%w matching %q", errNoResumeCommit, ref)
185		}
186		commit, err := lookup.repo.CommitObject(hash)
187		if err != nil {
188			return fmt.Errorf("failed to get commit %s: %w", abbreviateCommitHash(lookup.repo, hash), err)
189		}
190	
191		cpIDs := trailers.ParseAllCheckpoints(commit.Message)
192		if len(cpIDs) == 0 {
193			printNoTrailerMessage(w, lookup.repo, hash)
194			return NewSilentError(fmt.Errorf("commit %s has no Entire-Checkpoint trailer", abbreviateCommitHash(lookup.repo, hash)))
195		}
196	
197		cpID := cpIDs[0]
198		if len(cpIDs) > 1 {
199			latest, found, latestErr := resolveLatestCheckpoint(ctx, lookup.store, cpIDs)
200			if latestErr != nil {
201				return latestErr
202			}
203			if found {
204				cpID = latest.CheckpointID
205			}
206		}
207		return resumeResolvedCheckpoint(ctx, cmd, lookup, cpID, force)
208	}
209	
210	// resumeResolvedCheckpoint resumes one committed checkpoint: checks out the
211	// branch containing it (at the branch's current tip) when one exists, points
212	// at the owning worktree when that branch is checked out elsewhere, and falls
213	// back to restoring session logs in place when no local branch contains it.
214	func resumeResolvedCheckpoint(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, cpID id.CheckpointID, force bool) error {
215		w := cmd.OutOrStdout()
216	
217		branch := buildCheckpointBranchIndex(lookup.repo)[cpID.String()]
218		if branch == "" {
219			fmt.Fprintf(w, "Checkpoint %s is not on any local branch; restoring session logs without switching branches.\n", cpID)
220			return resumeByCheckpointID(ctx, w, cmd.ErrOrStderr(), cpID, force)
221		}
222		if otherPath, ok := branchCheckedOutElsewhere(ctx, branch); ok {
223			fmt.Fprintf(w, "Branch %q is already checked out at %s.\nResume this checkpoint from that worktree:\n\n  cd %s && entire checkpoint resume %s\n",
224				branch, otherPath, shellQuote(otherPath), cpID)
225			return nil
226		}
227		return resumeSessionOnBranch(ctx, cmd, branch, cpID, force)
228	}
229	
230	const checkpointResumePickerLimit = 20
231	
232	func runCheckpointResumePicker(ctx context.Context, cmd *cobra.Command, lookup *explainCheckpointLookup, force bool) error {
233		w := cmd.OutOrStdout()
234	
235		entries := recentCheckpoints(lookup.committed, checkpointResumePickerLimit)
236		if len(entries) == 0 {
237			fmt.Fprintln(w, "No committed checkpoints found.")
238			fmt.Fprintln(w, "Checkpoints are created when you commit during an agent session.")
239			return nil
240		}
241		branchIndex := buildCheckpointBranchIndex(lookup.repo)
242	
243		if !interactive.CanPromptInteractively() {
244			printCheckpointResumeList(w, entries, branchIndex)
245			return nil
246		}
247	
248		selected, ok, err := promptCheckpointSelection(ctx, entries, branchIndex)
249		if err != nil {
250			return err
251		}
252		if !ok {
253			fmt.Fprintln(w, "Resume cancelled.")
254			return nil
255		}
256		return resumeResolvedCheckpoint(ctx, cmd, lookup, selected, force)
257	}
258	
259	func recentCheckpoints(committed []checkpoint.CheckpointInfo, limit int) []checkpoint.CheckpointInfo {
260		sorted := make([]checkpoint.CheckpointInfo, len(committed))
261		copy(sorted, committed)
262		sort.SliceStable(sorted, func(i, j int) bool {
263			return sorted[i].CreatedAt.After(sorted[j].CreatedAt)
264		})
265		if len(sorted) > limit {
266			sorted = sorted[:limit]
267		}
268		return sorted
269	}
270	
271	func printCheckpointResumeList(w io.Writer, entries []checkpoint.CheckpointInfo, branchIndex map[string]string) {
272		fmt.Fprintf(w, "Recent checkpoints (newest first, up to %d):\n\n", checkpointResumePickerLimit)
273		for _, e := range entries {
274			branch := branchIndex[e.CheckpointID.String()]
275			if branch == "" {
276				branch = "-"
277			}
278			fmt.Fprintf(w, "  %s  %s  %s  %s\n", e.CheckpointID, e.CreatedAt.Local().Format("2006-01-02 15:04"), branch, checkpointAgentLabel(e))
279		}
280		fmt.Fprintln(w, "\nResume one with: entire checkpoint resume <checkpoint-id>")
281	}
282	
283	const checkpointPickerCancel = "cancel"
284	
285	func promptCheckpointSelection(ctx context.Context, entries []checkpoint.CheckpointInfo, branchIndex map[string]string) (id.CheckpointID, bool, error) {
286		options := make([]huh.Option[string], 0, len(entries)+1)
287		for _, e := range entries {
288			options = append(options, huh.NewOption(checkpointResumeOptionLabel(e, branchIndex), e.CheckpointID.String()))
289		}
290		options = append(options, huh.NewOption("Cancel", checkpointPickerCancel))
291	
292		var choice string
293		form := NewAccessibleForm(huh.NewGroup(
294			huh.NewSelect[string]().
295				Title("Resume which checkpoint?").
296				Description("Checks out the checkpoint's branch (when one contains it) and restores the session log.").
297				Options(options...).
298				Value(&choice),
299		))
300		if err := form.RunWithContext(ctx); err != nil {
301			if errors.Is(err, huh.ErrUserAborted) || errors.Is(err, context.Canceled) {
302				return "", false, nil
303			}
304			return "", false, fmt.Errorf("failed to pick checkpoint: %w", err)
305		}
306		if choice == checkpointPickerCancel {
307			return "", false, nil
308		}
309		return id.CheckpointID(choice), true, nil
310	}
311	
312	func checkpointResumeOptionLabel(e checkpoint.CheckpointInfo, branchIndex map[string]string) string {
313		branch := branchIndex[e.CheckpointID.String()]
314		if branch == "" {
315			branch = "no local branch"
316		}
317		return fmt.Sprintf("%s · %s · %s · %s", e.CheckpointID.DisplayShort(), branch, checkpointAgentLabel(e), timeAgo(e.CreatedAt))
318	}
319	
320	func checkpointAgentLabel(e checkpoint.CheckpointInfo) string {
321		if e.Agent == "" {
322			return unknownAgentLabel
323		}
324		return string(e.Agent)
325	}
